begin;
create or replace function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end$$;
insert into auth.users(id) values ('11020800-0000-4000-8000-000000000001'),('11020800-0000-4000-8000-000000000002');
insert into public.user_roles(user_id,role) values ('11020800-0000-4000-8000-000000000001','professional');
insert into public.professional_student_relationships(professional_user_id,student_user_id,status) values ('11020800-0000-4000-8000-000000000001','11020800-0000-4000-8000-000000000002','active');
insert into public.notification_devices(device_key,owner_id,endpoint,transport,subscription,preferences,timezone,lang,schedule) values(gen_random_uuid(),'11020800-0000-4000-8000-000000000001','https://fcm.googleapis.com/plan-switch-test','webpush','{}','{"professional":true}','UTC','pt','{}');
set local role authenticated;
select set_config('request.jwt.claim.sub','11020800-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('11020800-0000-4000-8000-000000000002','Full week','{"routines":[{"id":"a","name":"Monday","ex":[{"id":"0043","sets":3,"reps":10,"weight":20}]},{"id":"b","name":"Friday","ex":[{"id":"0043","sets":4,"reps":8,"weight":30}]}],"week":{"1":"a","5":"b"}}',0);
select public.send_student_plan('11020800-0000-4000-8000-000000000002',1);
select set_config('request.jwt.claim.sub','11020800-0000-4000-8000-000000000002',true);
select public.save_athlete_plan(0,'weekly','{"week":{"2":"11020800-0000-4000-8000-000000000010"},"dayPlan":{}}','[{"id":"11020800-0000-4000-8000-000000000010","title":"Personal","prescription":{"ex":[]}}]');
do $$declare pro uuid; own uuid; rev bigint; begin
 select id into pro from public.athlete_plan_library where user_id=auth.uid() and source_type='professional';
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 perform public.apply_library_plan(pro,rev);
 perform pg_temp.assert_true((select (select count(*) from jsonb_object_keys(schedule->'week'))=2 from public.athlete_schedules where user_id=auth.uid()),'one application installs both professional days');
 own:=public.save_personal_library_plan('Mine');
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 perform public.apply_library_plan(pro,rev);
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 perform public.apply_library_plan(own,rev);
 perform pg_temp.assert_true((select schedule->'week'='{"2":"11020800-0000-4000-8000-000000000010"}'::jsonb and not schedule ? 'assignedProgram' from public.athlete_schedules where user_id=auth.uid()),'removal restores whole personal week');
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 begin perform public.apply_library_plan(pro,rev-1); raise exception 'stale accepted'; exception when serialization_failure then null; end;
 perform public.apply_library_plan(pro,rev);
end$$;
reset role;
select pg_temp.assert_true((select count(*)=2 from public.notification_events where owner_id='11020800-0000-4000-8000-000000000001' and kind='student_plan_selected'),'initial selection and return notify once each; same selection and conflict do not');
select pg_temp.assert_true((select count(*)=1 from public.notification_events where owner_id='11020800-0000-4000-8000-000000000001' and kind='student_plan_left'),'leaving notifies trainer once');
set local role authenticated;
select set_config('request.jwt.claim.sub','11020800-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select exists(select 1 from jsonb_array_elements(assignments) a where (a->>'is_selected')::boolean) from public.professional_client_detail('11020800-0000-4000-8000-000000000002')),'trainer detail reports actual selection');
select public.save_student_plan_draft('11020800-0000-4000-8000-000000000002','Updated Monday','{"routines":[{"id":"a","name":"Monday updated","ex":[{"id":"0043","sets":5,"reps":6,"weight":40}]},{"id":"b","name":"Friday unchanged","ex":[{"id":"0043","sets":4,"reps":8,"weight":30}]}],"week":{"1":"a","5":"b"}}',1);
select public.send_student_plan('11020800-0000-4000-8000-000000000002',2);
reset role;
select pg_temp.assert_true((select version_number=1 from public.professional_workspace_students() where student_user_id='11020800-0000-4000-8000-000000000002'),'old selected version stays visible until new confirmation');
set local role authenticated;
select set_config('request.jwt.claim.sub','11020800-0000-4000-8000-000000000002',true);
do $$declare target uuid; rev bigint; begin
 select (x->>'id')::uuid into target from jsonb_array_elements(public.athlete_plan_library_page()->'items') x where x->'version'->>'version_number'='2';
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 perform public.apply_library_plan(target,rev);
 perform pg_temp.assert_true((select count(*)=2 from public.athlete_routines where user_id=auth.uid() and prescription->>'assigned'='true'),'updated and unchanged workouts both applied');
 perform pg_temp.assert_true((select count(*)=1 from public.athlete_routines where user_id=auth.uid() and title='Friday unchanged'),'unchanged day still present');
end$$;
rollback;
